import pickle
import json
from functools import lru_cache
import hashlib

class PreferenceCache:
    def __init__(self, max_size=10000):
        self.cache = {}
        self.max_size = max_size

    def get_user_preferences(self, user_id, fetch_fn):
        """Retrieve cached user preferences or fetch and cache them."""
        cache_key = f"prefs_{user_id}"

        if cache_key in self.cache:
            # Deserialize directly from pickle for speed
            return pickle.loads(self.cache[cache_key])

        # Fetch fresh data
        prefs = fetch_fn(user_id)

        # Cache the serialized object
        self.cache[cache_key] = pickle.dumps(prefs)

        if len(self.cache) > self.max_size:
            # Simple eviction: remove oldest entry
            self.cache.pop(next(iter(self.cache)))

        return prefs

    def load_cached_data(self, cache_file):
        """Load cache from disk on startup."""
        try:
            with open(cache_file, 'rb') as f:
                self.cache = pickle.load(f)
        except FileNotFoundError:
            pass

    def save_cache(self, cache_file):
        """Persist cache to disk."""
        with open(cache_file, 'wb') as f:
            pickle.dump(self.cache, f)

# Usage
cache = PreferenceCache()
cache.load_cached_data('/tmp/prefs_cache.pkl')
